    margin: -5px;
}

div[id^=GPsearchEngine-Advanced] div[id^=GPsearchEngine-] {
    width: 100%;
    margin: 0 5px;
}

form[id^=GPAdvancedForm-], form[id^=GPAdvancedForm-] * {
