}

/* ScaleLine — bas-droite, à gauche de zoom/fullscreen */
.ol-scale-line {
  z-index: auto;
  left: auto;
  right: var(--ec-widget-panel-x);
  bottom: var(--ec-widget-gap);
  background: var(--background-default-grey, #fff);
}

.position-container-bottom-right:empty ~ .ol-scale-line {
  right: var(--ec-widget-gap);
}

.ec-embed-viewer[data-v-80e5210e] {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 500px;
}
.ec-embed-viewer__map[data-v-80e5210e] {
  width: 100%;
  height: 100%;
}

.ec-embed-viewer .ec-map-shell,
.ec-embed-viewer .ec-map-shell__map,
.ec-embed-viewer #gpu-map {
  width: 100%;
  height: 100%;
}
.ec-embed-viewer .ec-map-shell {
  container-type: size;
  container-name: map;
}

.ec-location-search[data-v-be2d8819] {
  position: relative;
  width: 100%;
}
.ec-location-search__suggestions[data-v-be2d8819] {
  position: absolute;
  z-index: 10;
  left: 0;
  right: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--background-default-grey, #fff);
  border: 1px solid var(--border-default-grey, #ddd);
  max-height: 16rem;
