}
/* SearchEngineAdvanced monté hors carte (accueil gpu-site / démo). */

.ec-search-engine-standalone {
  position: relative;
  width: 100%;
  z-index: 100;
  overflow: visible !important;
}

.ec-search-engine-standalone__map-host {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.ec-search-engine-standalone__widget {
  position: relative;
  width: 100%;
  overflow: visible !important;
}

/* Widget en flux : barre seule ; overlays en absolute */
.ec-search-engine-standalone .gpf-widget[id^='GPsearchEngine-Advanced'] {
  position: relative !important;
  top: auto !important;
  left: auto !important;
  max-width: 100%;
  width: 100%;
  max-height: none !important;
  overflow: visible !important;
}

.ec-search-engine-standalone .gpf-widget[id^='GPsearchEngine-Advanced'] > .gpf-widget[id^='GPsearchEngine-'] {
  position: relative !important;
  overflow: visible !important;
}

.ec-search-engine-standalone .GPSearchBar {
  width: 100%;
  position: relative;
}

/*
 * Suggestions : overlay sous la barre (ne pousse pas le layout).
 * Ne pas absouluter les listes internes — uniquement le conteneur.
 */
.ec-search-engine-standalone .GPautoCompleteContainer {
  position: absolute !important;
  left: 0;
  right: 0;
  top: 100%;
  width: 100% !important;
  margin: 0 !important;
  z-index: 200;
  background: var(--background-default-grey, #fff);
  box-shadow: 0 2px 6px 0 rgba(0, 0, 18, 0.16);
  max-height: min(50vh, 20rem);
  overflow: auto;
}

/* Conteneur visible (geopf retire gpf-hidden au focus / résultats) */
.ec-search-engine-standalone .GPautoCompleteContainer.gpf-visible,
.ec-search-engine-standalone .GPautoCompleteContainer.GPelementVisible {
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;
}

.ec-search-engine-standalone .GPautoCompleteList {
  position: static !important;
  margin: 0 !important;
  width: 100% !important;
}

.ec-search-engine-standalone .gpf-widget[id^='GPsearchEngine-Advanced'] > .GPAdvancedContainer,
.ec-search-engine-standalone .GPAdvancedContainer {
  position: absolute !important;
  left: 0;
  right: 0;
  top: 100%;
  width: 100% !important;
  max-width: 100% !important;
  z-index: 210;
  background: var(--background-default-grey, #fff);
  box-shadow: 0 2px 6px 0 rgba(0, 0, 18, 0.16);
  max-height: min(70vh, 28rem);
  overflow: auto;
}
